"use client";

import { Radio as BaseRadio } from "@base-ui/react/radio";
import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";
import type { BaseUIEvent } from "@base-ui/react/types";
import { clsx } from "clsx";
import type { ComponentPropsWithRef, KeyboardEvent, ReactNode } from "react";

import "./radio-group.css";

export type RadioGroupOrientation = "horizontal" | "vertical";

export type RadioGroupRootProps<Value> = BaseRadioGroup.Props<Value> & {
  loading?: boolean;
  orientation?: RadioGroupOrientation;
};

export function RadioGroupRoot<Value>({
  "aria-busy": ariaBusy,
  className,
  loading = false,
  onKeyDownCapture,
  orientation = "vertical",
  readOnly,
  ...props
}: RadioGroupRootProps<Value>) {
  const handleKeyDownCapture = (event: BaseUIEvent<KeyboardEvent<HTMLDivElement>>) => {
    onKeyDownCapture?.(event);
    const isVerticalArrow = event.key === "ArrowUp" || event.key === "ArrowDown";
    const isHorizontalArrow = event.key === "ArrowLeft" || event.key === "ArrowRight";
    if (
      (orientation === "vertical" && isHorizontalArrow) ||
      (orientation === "horizontal" && isVerticalArrow)
    ) {
      event.preventDefault();
      event.stopPropagation();
    }
  };

  return (
    <BaseRadioGroup
      {...props}
      aria-busy={loading || ariaBusy || undefined}
      aria-orientation={orientation}
      className={clsx("mfd-radio-group", className)}
      data-orientation={orientation}
      onKeyDownCapture={handleKeyDownCapture}
      readOnly={loading || readOnly}
    />
  );
}

export type RadioGroupItemProps<Value> = ComponentPropsWithRef<typeof BaseRadio.Root<Value>>;

export function RadioGroupItem<Value>({
  className,
  children,
  ...props
}: RadioGroupItemProps<Value>) {
  return (
    <BaseRadio.Root {...props} className={clsx("mfd-radio-group__item", className)}>
      {children ?? <BaseRadio.Indicator className="mfd-radio-group__indicator" />}
    </BaseRadio.Root>
  );
}

export type RadioGroupIndicatorProps = ComponentPropsWithRef<typeof BaseRadio.Indicator>;

export function RadioGroupIndicator({ className, ...props }: RadioGroupIndicatorProps) {
  return (
    <BaseRadio.Indicator {...props} className={clsx("mfd-radio-group__indicator", className)} />
  );
}

export type RadioCardProps<Value> = Omit<RadioGroupItemProps<Value>, "children"> & {
  children: ReactNode;
  description?: ReactNode;
  preview?: ReactNode;
};

export function RadioCard<Value>({
  children,
  className,
  description,
  preview,
  ...props
}: RadioCardProps<Value>) {
  return (
    <label className={clsx("mfd-radio-card", className)}>
      <RadioGroupItem {...props}>
        <RadioGroupIndicator />
      </RadioGroupItem>
      {preview ? (
        <span aria-hidden="true" className="mfd-radio-card__preview">
          {preview}
        </span>
      ) : null}
      <span className="mfd-radio-card__content">
        <span className="mfd-radio-card__label">{children}</span>
        {description ? <span className="mfd-radio-card__description">{description}</span> : null}
      </span>
    </label>
  );
}

export type RadioGroupParts = Readonly<{
  Root: typeof RadioGroupRoot;
  Item: typeof RadioGroupItem;
  Indicator: typeof RadioGroupIndicator;
  Card: typeof RadioCard;
}>;

export const RadioGroup: RadioGroupParts = {
  Root: RadioGroupRoot,
  Item: RadioGroupItem,
  Indicator: RadioGroupIndicator,
  Card: RadioCard,
};

.mfd-radio-group {
  align-items: stretch;
  display: flex;
  flex-direction: column;
  gap: var(--mfd-space-field-gap);
}

.mfd-radio-group[data-orientation="horizontal"] {
  flex-direction: row;
  flex-wrap: wrap;
}

.mfd-radio-group__item {
  align-items: center;
  appearance: none;
  color: var(--mfd-color-text-primary);
  display: inline-flex;
  flex: none;
  height: var(--mfd-size-hit-target-minimum);
  justify-content: center;
  margin: 0;
  padding: 0;
  position: relative;
  width: var(--mfd-size-hit-target-minimum);
}

.mfd-radio-group__item::before {
  background: var(--mfd-color-bg-canvas);
  border: 1px solid var(--mfd-color-border-default);
  border-radius: var(--mfd-radius-pill);
  content: "";
  height: var(--mfd-icon-size-md);
  position: absolute;
  width: var(--mfd-icon-size-md);
}

.mfd-radio-group__item[data-checked]::before {
  background: var(--mfd-color-accent-solid);
  border-color: var(--mfd-color-accent-solid);
}

.mfd-radio-group__item[data-checked] {
  color: var(--mfd-color-accent-on-solid);
}

.mfd-radio-group__item:focus-visible {
  outline: 2px solid var(--mfd-color-border-focus);
  outline-offset: 3px;
}

.mfd-radio-group__item[aria-disabled="true"],
.mfd-radio-group[aria-disabled="true"] {
  cursor: not-allowed;
  opacity: 0.65;
}

.mfd-radio-group__indicator {
  align-items: center;
  display: flex;
  justify-content: center;
}

.mfd-radio-group__indicator[data-unchecked] {
  display: none;
}

.mfd-radio-group__indicator::before {
  background: currentColor;
  border-radius: var(--mfd-radius-pill);
  content: "";
  display: block;
  height: var(--mfd-space-inline-xs);
  width: var(--mfd-space-inline-xs);
}

.mfd-radio-card {
  align-items: flex-start;
  background: var(--mfd-color-bg-surface);
  border: 1px solid var(--mfd-color-border-subtle);
  border-radius: var(--mfd-radius-surface);
  cursor: pointer;
  display: flex;
  gap: var(--mfd-space-inline-md);
  min-height: max(5rem, var(--mfd-size-hit-target-minimum));
  padding: var(--mfd-space-inline-md);
  position: relative;
}

.mfd-radio-card:has(.mfd-radio-group__item[data-checked]) {
  border-color: var(--mfd-color-accent-solid);
  box-shadow: inset 0 0 0 1px var(--mfd-color-accent-solid);
}

.mfd-radio-card:has(.mfd-radio-group__item:focus-visible) {
  outline: 2px solid var(--mfd-color-border-focus);
  outline-offset: 2px;
}

.mfd-radio-card__preview {
  align-items: center;
  background: var(--mfd-color-accent-bg);
  border: 1px solid var(--mfd-color-accent-border);
  border-radius: var(--mfd-radius-control);
  color: var(--mfd-color-accent-text);
  display: inline-flex;
  flex: none;
  height: 2.5rem;
  justify-content: center;
  min-width: 2.5rem;
  padding-inline: var(--mfd-space-inline-sm);
}

.mfd-radio-card__content {
  display: grid;
  gap: var(--mfd-space-stack-xs);
  min-width: 0;
}

.mfd-radio-card__label {
  font-weight: var(--mfd-typography-label-font-weight);
}

.mfd-radio-card__description {
  color: var(--mfd-color-text-secondary);
  font-size: var(--mfd-typography-caption-font-size);
  line-height: var(--mfd-typography-caption-line-height);
}

@media (max-width: 40rem) {
  .mfd-radio-group[data-orientation="horizontal"] {
    flex-direction: column;
  }

  .mfd-radio-card {
    min-width: 100%;
  }
}

@media (forced-colors: active) {
  .mfd-radio-group__item[data-checked]::before {
    background: Highlight;
    border-color: Highlight;
  }

  .mfd-radio-group__item[data-checked] {
    color: HighlightText;
  }

  .mfd-radio-card:has(.mfd-radio-group__item[data-checked]) {
    border-color: Highlight;
    box-shadow: inset 0 0 0 1px Highlight;
  }
}
